import { useState } from "react";

function PostForm({ token, onPostAdded, categoryId }) {
    const [title, setTitle] = useState("");
    const [content, setContent] = useState("");
    const [error, setError] = useState("");

    const handleSubmit = async (e) => {
        e.preventDefault();
        if (!title || !content || !categoryId) {
            setError("Заповніть усі поля та оберіть категорію");
            return;
        }

        try {
            const res = await fetch("http://localhost:5000/api/posts", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    Authorization: `Bearer ${token}`,
                },
                body: JSON.stringify({ title, content, category_id: categoryId }),
            });

            const data = await res.json();

            if (!res.ok) {
                setError(data.message || "Помилка при створенні поста");
            } else {
                setTitle("");
                setContent("");
                setError("");
                if (onPostAdded) onPostAdded();
            }
        } catch (err) {
            console.error(err);
            setError("Помилка при запиті до сервера");
        }
    };

    return (
        <form onSubmit={handleSubmit} className="space-y-4">
            {error && <p className="text-red-500">{error}</p>}
            <input
                type="text"
                placeholder="Заголовок поста"
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                className="input-field"
            />
            <textarea
                placeholder="Текст поста"
                value={content}
                onChange={(e) => setContent(e.target.value)}
                rows={4}
                className="input-field"
            />
            <button type="submit" className="btn-primary w-full">
                Опублікувати
            </button>
        </form>
    );
}

export default PostForm;
